    id: "eng-2025-hl-q7-c-ii", topicId: "eng-1-9", conceptId: "differentiate-between-methods-recycling-thermoplastics-thermosetting",
    section: "A", questionRef: "2025 HL Q7(c)(ii)",
    stem: "Seabin™",
    questionText: "Differentiate between the methods of recycling thermoplastics and thermosetting plastics.",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 8,
    rows: [
    { id: "r-1", kind: "point", verbatim: "Thermoplastics can be recycled relatively easily. They can be melted and reshaped multiple times without significantly altering their chemical structure or properties.", marks: null },
    { id: "r-2", kind: "point", verbatim: "The recycling process for thermoplastics typically involves collecting, sorting, cleaning, shredding, and then melting the plastic before remoulding it into new products. Examples include polyethylene (PE), polypropylene (PP) and polyvinyl chloride (PVC).", marks: null },
    { id: "r-3", kind: "point", verbatim: "Thermosetting plastics are much harder to recycle. Once they have been cured and set into a rigid form, they cannot be remelted or reshaped due to their cross-linked chemical structure.", marks: null },
    { id: "r-4", kind: "point", verbatim: "This makes traditional recycling methods like melting and remoulding ineffective.", marks: null },
    { id: "r-5", kind: "point", verbatim: "Recycling thermosetting plastics usually involves grinding them into small particles that can be used as fillers or in composite materials, rather than being reformed into new plastic products.", marks: null },
    ],
